import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        FastReader r = new FastReader();
        int n = r.nextInt();
        long k = r.nextLong();
        long[] key = new long[n];
        for (int i = 0; i < n; i++) { long a = r.nextLong(), b = r.nextLong(); key[i] = (a << 31) | b; }
        Arrays.sort(key);
        long[] ms = new long[n], me = new long[n];
        int m = 0;
        for (long kv : key) {
            long a = kv >> 31, b = kv & ((1L << 31) - 1);
            if (m > 0 && a <= me[m - 1]) me[m - 1] = Math.max(me[m - 1], b);
            else { ms[m] = a; me[m] = b; m++; }
        }
        int left = 0, ans = m;
        for (int right = 0; right < m; right++) {
            while (ms[right] - me[left] > k) left++;
            ans = Math.min(ans, m - (right - left));
        }
        System.out.println(ans);
    }
}

final class FastReader {
    private final java.io.InputStream in = System.in;
    private final byte[] buf = new byte[1 << 16];
    private int len = 0, ptr = 0;

    private int read() throws java.io.IOException {
        if (ptr == len) {
            len = in.read(buf, 0, buf.length);
            ptr = 0;
            if (len <= 0) { len = 0; return -1; }
        }
        return buf[ptr++];
    }

    String next() throws java.io.IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') { sb.append((char) c); c = read(); }
        return sb.toString();
    }

    long nextLong() throws java.io.IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') { r = r * 10 + (c - '0'); c = read(); }
        return neg ? -r : r;
    }

    int nextInt() throws java.io.IOException { return (int) nextLong(); }
}

