	"os"
	"slices"
)

func main() {
	n, k := readInt(), readInt()
	v := make([][2]int, n)
	for i := range v {
		v[i] = [2]int{readInt(), readInt()}
	}
	slices.SortFunc(v, func(a, b [2]int) int {
		if a[0] != b[0] {
			return cmp.Compare(a[0], b[0])
		}
		return cmp.Compare(a[1], b[1])
	})
	var m [][2]int
	for _, p := range v {
		if len(m) > 0 && p[0] <= m[len(m)-1][1] {
			m[len(m)-1][1] = max(m[len(m)-1][1], p[1])
		} else {
			m = append(m, p)
		}
	}
	left, ans := 0, len(m)
	for right := range m {
		for m[right][0]-m[left][1] > k {
			left++
		}
		ans = min(ans, len(m)-(right-left))
	}
	fmt.Println(ans)
}

var reader = bufio.NewReaderSize(os.Stdin, 1<<16)

func readToken() string {
	b, err := reader.ReadByte()
	for err == nil && b <= ' ' {
		b, err = reader.ReadByte()
	}
	var buf []byte
	for err == nil && b > ' ' {
		buf = append(buf, b)
		b, err = reader.ReadByte()
	}
	return string(buf)
}

func readInt() int {
	b, err := reader.ReadByte()
	for err == nil && b <= ' ' {
		b, err = reader.ReadByte()
	}
	neg := false
	if b == '-' {
		neg = true
		b, err = reader.ReadByte()
	}
	r := 0
	for err == nil && b >= '0' && b <= '9' {
		r = r*10 + int(b-'0')
		b, err = reader.ReadByte()
	}
	if neg {
		return -r
	}
	return r
}
